INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MoonQuest', 'MoonQuest is a procedurally-generated adventure game with roguelike and minecraftian gameplay. Each game presents a new world to explore in your quest to illuminate the endless night. Seek out the lost forest, delve into the spider caves, storm the castle of the Silver King, discover vast seams of gold ore, and craft a hat of such splendour that the cosmos will be jealous.' FROM games WHERE igdb_id = 105112 ON CONFLICT (game_id, language_code) DO NOTHING;
