INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Buried Stars', '"BURIED STARS" is a new mystery Communication x Survival x Adventure game developed by Team Largo and LINE Games Corporation. BURIED STARS is an adventure game that takes place at a collapse site of a live audition show. The trapped survivors communicate with each other, and through social media, while waiting for the rescue team’s arrival. But an unexpected turn of events splits them apart and drives them into a corner.' FROM games WHERE igdb_id = 137192 ON CONFLICT (game_id, language_code) DO NOTHING;
