INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deep Diving Adventures', 'Deep Diving Adventures will enable you to experience what it takes to be a modern diver. With relaxing exploration, you will discover the uncharted waters of the world while carefully monitoring your oxygen level and decompression. Gather forsaken relics, visit sunken vessels, discover unknown species and be rewarded by Professor Adams for your findings. Each submerge gives you the opportunity to uncover mysteries that would prefer to remain forever forgotten, such as the lost city of Atlantis.' FROM games WHERE igdb_id = 131978 ON CONFLICT (game_id, language_code) DO NOTHING;
