INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grisaia Phantom Trigger Vol.7', 'As daily life goes on unchanged, the girls - and Haruto - continue to sharpen their fangs. They are summoned for a mission of unprecedented scale, against the religious organization "TFA", where Enishi and Kuroe await. What kind of hellish scenes will Arisaka have to face on the battlefield?' FROM games WHERE igdb_id = 135819 ON CONFLICT (game_id, language_code) DO NOTHING;
